// === Tab: mySketch ===
//for the #wccChallenge on theme of "Big Sky". 
//Finally knuckled down and started to learn shaders.
//The shader sky is pretty rudimentary I'll admit, but
//I think it works with the stylized folk-arty trees. 
//Got very excited when I realized how to combine a shader with regular p5js drawing.
//Lots of possibilites to explore with that.

//Aesthetically, this sketch looks particularly American to me for some reason.

let sky;
branches=[]
let growthRate=2
let b

function preload(){
	sky = createShader(vert, frag)
}

function setup() {
	createCanvas(windowWidth,windowHeight,WEBGL);
	noStroke()
	background(0);
	b= createGraphics(windowWidth, windowHeight)

	for(let x=0; x<b.width; x+=75){
		let h=map(Math.abs(x-width/2), 50, b.width/2, b.height/10, b.height/2)
		branches.push(new branching(x, b.height, h+random(-h/10, h/10), 0, random(1000)))
	}
}

function draw() {
	shader(sky)
	sky.setUniform('u_resolution',[windowWidth,windowHeight])
	sky.setUniform('u_time',millis()/600)
	sky.setUniform('u_mouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height])
	rect(-width/2,-height/2,width,height)


	for(let branching of branches){
		branching.show()
		branching.grow()
		branching.branch()
	}
	image(b, -width/2, -height/2, 0)
}


class branching{
	constructor(x, y, length, a, theta){
		this.x=x
		this.y=y
		this.length=length
		this.a=a
		this.theta=theta
		this.currentL=0
		this.toBranch= floor(this.length/8)
		this.girth=0
		this.xOffset=0
		this.yOffset=0
	}



	show(){
		b.push()
		b.noStroke()
		b.fill(0)
		b.translate(this.x, this.y)
		b.rotate(this.a)
		this.xOffset= map(noise(this.currentL/100, this.theta, this.x), 0, 1, -this.length/20, this.length/20)
		this.girth=map(this.currentL, 0, -this.length, this.length/20, 0)
		b.circle(this.xOffset, this.currentL+this.yOffset, this.girth)
		b.pop()		
	}

	grow(){
		if(this.currentL>-this.length){
		this.currentL-= growthRate
			this.theta+=0.0001
		} else{
			 let index = branches.indexOf(this);
      branches.splice(index, 1);

		}
	}

	branch(){
		if(this.currentL<=-this.length/2.7 && this.currentL%this.toBranch==0 && this.length>15){
			let newX=(this.x+cos(this.a-PI/2)*-this.currentL)+this.xOffset
			let newY=this.y+sin(this.a-PI/2)*-this.currentL
			let newA1=this.a-PI/2+ random(PI/6)
			let newA2=this.a+PI/2+ random(-PI/6)
			let randomScaling= random(18, 22)
			branches.push(new branching(newX, newY, this.girth*randomScaling, newA1, this.theta))
			branches.push(new branching(newX, newY, this.girth*randomScaling, newA2, this.theta))
		}
	}
}



// === Tab: frag ===
const frag = `
	precision mediump float;

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;
	uniform vec3 u_lightDir;
	uniform vec3 u_col;
	uniform mat3 uNormalMatrix;
	uniform float u_pixelDensity;
	uniform sampler2D u_tex;

	//attributes, in
	varying vec4 var_centerGlPosition;
	varying vec3 var_vertNormal;
	varying vec2 var_vertTexCoord;


float random (in vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(12.9898,78.233)))
                 * 43758.5453123);
}


float noise (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = smoothstep(0.,1.,f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}




	void main(){

	vec2 st = gl_FragCoord.xy/u_resolution.xy;
		float wave= smoothstep(0.2, 1., noise(st*32.-u_time)/1.8);
		vec2 pos= mix(vec2(wave), vec2(st.x*5., st.y*10.), 0.79);
    float n = noise(pos);
    gl_FragColor = vec4(0.2+n*0.77-smoothstep(0.5, 1.0, st.y)*0.2, 0.6+n*0.3, 1.+ n/0.3,  smoothstep(0.0,0.1,st.y)-random(st)*0.2);

	}
`





// === Tab: vert ===
//ref from https://www.openprocessing.org/sketch/881537

const vert = `
	precision mediump float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

